import React, { useState } from 'react';

const VirtualAssistant = ({ setActiveItem }) => {
  const [openSections, setOpenSections] = useState({});

  const toggleSection = (title) => {
    setOpenSections((prev) => ({
      ...prev,
      [title]: !prev[title]
    }));
  };

  const menuSections = [
    {
      title: '📊 Rendimiento',
      items: [
        { id: 'grades', label: 'Ver notas de mis hijos' },
        { id: 'attendance', label: 'Consultar asistencia' }
      ]
    },
    {
      title: '📝 Tareas',
      items: [
        { id: 'pending-tasks', label: 'Tareas pendientes' }
      ]
    }
  ];

  const handleActionClick = (itemId) => {
    setActiveItem(itemId);
  };

  return (
    <div className="fixed bottom-6 right-6 z-50">
      <div className="bg-white rounded-xl shadow-xl w-64 mb-4 overflow-hidden">
        <div className="bg-blue-600 text-white p-3">
          <h3 className="font-medium">¿En qué puedo ayudarte hoy?</h3>
        </div>

        <div className="space-y-4">
          {menuSections.map((section) => (
            <div key={section.title} className="space-y-1">
              <button
                onClick={() => toggleSection(section.title)}
                className="w-full text-left text-sm font-semibold text-gray-700 uppercase tracking-wider mb-1 px-2 flex items-center gap-2 hover:text-white"
              >
                <span>{section.title.split(' ')[0]}</span>
                <span className="flex-1">{section.title.split(' ').slice(1).join(' ')}</span>
                <span>{openSections[section.title] ? '▲' : '▼'}</span>
              </button>

              {openSections[section.title] && (
                <ul className="space-y-1">
                  {section.items.map((item) => (
                    <li key={item.id}>
                      <button
                        onClick={() => handleActionClick(item.id)}
                        className="w-full text-left px-4 py-2 rounded-lg transition text-sm flex items-center gap-2 hover:bg-gray-200"
                      >
                        <span className="text-lg">{section.title.includes('📊') ? '📊' : '📝'}</span>
                        <span>{item.label}</span>
                      </button>
                    </li>
                  ))}
                </ul>
              )}
            </div>
          ))}
        </div>
      </div>

      <button
        onClick={() => setOpenSections({})} // Close all sections on this button click if desired.
        className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-3 rounded-full shadow-lg transition"
      >
        🤖
      </button>
    </div>
  );
};

export default VirtualAssistant;
